// Inspections, observations, PPE and contractor safety (part 19.04). Scheduled inspections use the checklists of 18.01 and a failed one raises an observation; safety observation cards are closed by someone other than the person who acted on them and escalate when
// they pass their SLA (BR-01); a penalty against a subcontractor goes through approval (HSE engineer, project manager); PPE is issued by QR with an acknowledgement and falls due for replacement; the safety equipment register watches expiry; the contractor score is worked out from live data.
for (const [key, type, def, description, min, max] of [
  ['hse.observation.sla_hours_critical', 'integer', 8, 'Hours within which a critical observation must be closed before it escalates.', 1, 720],
  ['hse.observation.sla_hours_high', 'integer', 24, 'Hours within which a high observation must be closed before it escalates.', 1, 720],
  ['hse.observation.sla_hours_medium', 'integer', 72, 'Hours within which a medium observation must be closed before it escalates.', 1, 2160],
  ['hse.observation.sla_hours_low', 'integer', 168, 'Hours within which a low observation must be closed before it escalates.', 1, 4320],
  ['hse.equipment.expiry_warn_days', 'integer', 30, 'Days before the expiry of safety equipment that the HSE team is told.', 1, 365],
  ['hse.contractor.weight_violation', 'integer', 5, 'Points taken off a contractor safety score for each violation observed in the month.', 0, 50],
  ['hse.contractor.weight_incident', 'integer', 15, 'Points taken off a contractor safety score for each incident involving their workers in the month.', 0, 100]]) {
  if (!parameterRegistry.get(key)) parameterRegistry.define({ key, dataType: type, default: def, scopes: ['system', 'company'], description, min, max });
}
export const OBS_TYPES = { UNSAFE_ACT: 'Unsafe act', UNSAFE_CONDITION: 'Unsafe condition', POSITIVE: 'Positive observation' };
export const OBS_STATE = { OPEN: 'Open', ACTION_DONE: 'Action done, to be verified', CLOSED: 'Closed', CANCELLED: 'Cancelled' };
export const SEVERITIES = { LOW: 'Low', MEDIUM: 'Medium', HIGH: 'High', CRITICAL: 'Critical' };
export const REGISTER_TYPES = { SCAFFOLD: 'Scaffold', EQUIPMENT: 'Equipment', ELECTRICAL: 'Electrical', HOUSEKEEPING: 'Housekeeping', FIRE_EXTINGUISHER: 'Fire extinguisher', OTHER: 'Other' };
export const EQUIP_TYPES = { FIRE_EXTINGUISHER: 'Fire extinguisher', FIRST_AID_BOX: 'First aid box', EYE_WASH: 'Eye wash', SMOKE_DETECTOR: 'Smoke detector', EMERGENCY_LIGHT: 'Emergency light', SPILL_KIT: 'Spill kit', OTHER: 'Other' };
export const PPE_STATE = { ISSUED: 'Issued', RETURNED: 'Returned', REPLACED: 'Replaced', CANCELLED: 'Cancelled' };
const json = (s, d) => { try { return JSON.parse(s); } catch { return d; } };
const addDays = (iso, n) => new Date(Date.parse(`${iso}T00:00:00Z`) + n * 86_400_000).toISOString().slice(0, 10);
const dayDiff = (a, b) => Math.round((Date.parse(`${String(a).slice(0, 10)}T00:00:00Z`) - Date.parse(`${String(b).slice(0, 10)}T00:00:00Z`)) / 86_400_000);
const band = (s) => (s >= 85 ? 'A' : s >= 70 ? 'B' : s >= 50 ? 'C' : 'D');

