    const o = { id: r.id, docNo: r.doc_no, projectId: r.org_project_id, project: pcode(r.org_project_id), siteId: r.org_site_id, obsType: r.obs_type, typeLabel: OBS_TYPES[r.obs_type], description: r.description, locationId: r.location_id, locationText: r.location_text, responsibleType: r.responsible_type, responsibleId: r.responsible_id, responsible: partnerName(r.responsible_id), severity: r.severity, severityLabel: SEVERITIES[r.severity], immediateAction: r.immediate_action, actionRequired: r.action_required, dueAt: r.due_at, overdue: Boolean(open && r.due_at && r.due_at < nowLocal() && r.obs_type !== 'POSITIVE'), escalationLevel: r.escalation_level, observedBy: r.observed_by, photoCount: json(r.photo_file_ids, []).length, state: st, stateLabel: OBS_STATE[st], source: r.inspection_id ? 'INSPECTION' : 'CARD', actionDoneBy: r.action_done_by, actionDoneOn: r.action_done_on, actionNote: r.action_note, closedBy: r.closed_by, closedOn: r.closed_on,
      penalty: r.penalty_amount > 0 && (fin || c('view')) ? { amount: r.penalty_amount / 100, reason: r.penalty_reason } : null, status: r.status, statusLabel: STATUS[r.status], version: r.version,
      can: { ...base0, edit: st === 'OPEN' && c('edit') && flow.EDITABLE.includes(r.status), act: st === 'OPEN' && (c('act') || c('edit')), close: st === 'ACTION_DONE' && c('close') && !same(r.action_done_by, actor.user), reopen: st === 'ACTION_DONE' && c('close'), photo: open && (c('create') || c('edit')), penalty: open !== undefined && r.responsible_type === 'SUBCONTRACTOR' && r.obs_type !== 'POSITIVE' && c('penalty') && flow.EDITABLE.includes(r.status) && st !== 'CANCELLED', cancel: ['OPEN', 'ACTION_DONE'].includes(st) && c('cancel') } };
    if (detail) Object.assign(o, flow.approveInfo(actor, r), { photos: json(r.photo_file_ids, []), cancelReason: r.cancel_reason });
