    audit(actor, 'hse_observations', id, 'create', actor.companyId); const f = db.prepare('SELECT * FROM hse_observations WHERE id = ?').get(id); evt('hse.observation.raised', actor, f.company_id, 'hse_observations', id, dataOf(f), pj);
