    submit(actor, id) { flow.submit(actor, id); return get(actor, id); }, withdraw: (actor, id, b) => { flow.withdraw(actor, id, b); return get(actor, id); },
    cancel(actor, id, { reason }) { const r = flow.row(actor, id, 'hse.observation.cancel'); if (!['OPEN', 'ACTION_DONE'].includes(r.obs_status)) throw unprocessable('Only an open observation is cancelled.'); if (r.status === 'SUBMITTED') flow.cancel(actor, id, { reason }); db.prepare("UPDATE hse_observations SET obs_status = 'CANCELLED', cancel_reason = ?, updated_by = ?, updated_at = ?, version = version + 1 WHERE id = ?").run(reason, actor.user, nowIso(), r.id); audit(actor, 'hse_observations', r.id, 'cancel', r.company_id, { reason }); return get(actor, r.id); },
